// components/EventProfileModal.jsx
//
// The profile for an attendee, a talent or an exhibitor, opened from the event page and
// from the entity lists.
//
// It used to be a full-screen takeover with the content pinned to `maxWidth: 400px`, so
// on a laptop it read as a phone screen floating in the middle of the browser. It now has
// two shapes: a full-screen sheet on phones (unchanged behaviour, correct for the device)
// and a centred dialog with a two-column body on desktop.
//
// The action row is generated by utils/entityActions.js, so every button that renders has
// a destination: the buttons that used to do nothing (CONTACT, VIEW PORTFOLIO) now open a
// mail client or the exhibitor's own site, and VIEW PROFILE resolves the username the
// /profile/<username> route actually needs.
import { useEffect, useState } from 'react';
import { useRouter } from 'next/router';
import { ArrowLeft, X, MessageSquare, Mail, ExternalLink, UserRound } from 'lucide-react';
import { useIsDesktop } from '../hooks/useIsDesktop';
import { entityActions, entityFallbackLine } from '../utils/entityActions';

const INK = '#151413';
const LEAF = '#ABD49E';
const LEAF_08 = 'rgba(171,212,158,0.08)';
const LEAF_30 = 'rgba(171,212,158,0.3)';

// Entities arrive from different endpoints with different image field names.
const imgOf = (o = {}) => o.image || o.avatar || o.photo || o.coverImage || o.logo || null;

const TYPE_LABEL = { ATTENDEE: 'ATTENDEE', TALENT: 'TALENT', EXHIBITOR: 'EXHIBITOR' };
const ACTION_ICON = { message: MessageSquare, profile: UserRound, mailto: Mail, external: ExternalLink };

// Shared geometry: 44px+ touch target on phones, auto-width and roomier on desktop so the
// two or three buttons sit as a row instead of stretching across the dialog.
function actionStyle(isDesktop, filled) {
  return {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 10,
    minHeight: isDesktop ? 46 : 50,
    width: isDesktop ? 'auto' : '100%',
    minWidth: isDesktop ? 170 : 0,
    padding: isDesktop ? '0 24px' : '0 18px',
    fontSize: 13,
    fontWeight: 700,
    letterSpacing: 0.5,
    textDecoration: 'none',
    cursor: 'pointer',
    border: `1px solid ${LEAF}`,
    backgroundColor: filled ? LEAF : 'transparent',
    color: filled ? INK : LEAF,
  };
}

export default function EventProfileModal({ entity, onClose, eventName = 'Event Name' }) {
  const router = useRouter();
  const isDesktop = useIsDesktop();
  const [profileUsername, setProfileUsername] = useState(null);
  const [profileState, setProfileState] = useState('idle');   // idle | loading | done | missing

  const type = entity?.type || 'ATTENDEE';
  const userId = entity?.userId ? String(entity.userId) : null;

  // Escape closes the dialog, and the page behind it does not scroll while it is open.
  useEffect(() => {
    if (!entity) return;
    const onKey = (e) => { if (e.key === 'Escape') onClose?.(); };
    window.addEventListener('keydown', onKey);
    const previous = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = previous;
    };
  }, [entity, onClose]);

  // VIEW PROFILE needs a username (the route is /profile/[username]) while an entity only
  // carries a userId, so resolve it once on open. A lookup that fails drops the button
  // rather than letting it land on "Profile not found".
  useEffect(() => {
    if (!userId) { setProfileUsername(null); setProfileState('idle'); return; }
    let cancelled = false;
    setProfileState('loading');
    fetch(`/api/users/${userId}`)
      .then(r => (r.ok ? r.json() : null))
      .then(d => {
        if (cancelled) return;
        const username = d?.data?.username;
        setProfileUsername(username ? String(username) : null);
        setProfileState(username ? 'done' : 'missing');
      })
      .catch(() => { if (!cancelled) setProfileState('missing'); });
    return () => { cancelled = true; };
  }, [userId]);

  if (!entity) return null;


  const actions = entityActions(entity, type).filter(
    a => a.kind !== 'profile' || profileState !== 'missing'
  );
  const contactActions = actions.filter(a => a.kind === 'mailto' || a.kind === 'external');
  const localActions = actions.filter(a => a.kind === 'message' || a.kind === 'profile');
  const primary = (localActions[0] || contactActions[0] || {}).id;

  const imageSrc = imgOf(entity);
  const products = Array.isArray(entity.products) ? entity.products : [];

  const openAction = (action) => {
    if (action.kind === 'message') {
      router.push(`/chat?to=${action.userId}&name=${encodeURIComponent(action.name || entity.name || '')}`);
      return;
    }
    if (action.kind === 'profile' && profileUsername) {
      router.push(`/profile/${profileUsername}`);
    }
  };

  // One renderer for both shapes — only the column count, the image ratio and the button
  // flow change between phone and desktop.
  const actionRow = (
    actions.length === 0 ? (
      <p style={{ margin: 0, fontSize: 13, lineHeight: 1.6, opacity: 0.6 }}>{entityFallbackLine(entity, type)}</p>
    ) : (
      <div style={{ display: 'flex', flexDirection: isDesktop ? 'row' : 'column', flexWrap: 'wrap', gap: isDesktop ? 12 : 10 }}>
        {actions.map((action) => {
          const Icon = ACTION_ICON[action.kind];
          const filled = action.id === primary;
          const content = (
            <>
              {Icon && <Icon size={16} />}
              {action.label}
            </>
          );
          if (action.kind === 'mailto' || action.kind === 'external') {
            const external = action.kind === 'external';
            return (
              <a
                key={action.id}
                href={action.href}
                target={external ? '_blank' : undefined}
                rel={external ? 'noreferrer noopener' : undefined}
                style={actionStyle(isDesktop, filled)}
              >
                {content}
              </a>
            );
          }
          const pending = action.kind === 'profile' && profileState === 'loading';
          return (
            <button
              key={action.id}
              type="button"
              onClick={() => openAction(action)}
              disabled={pending}
              style={{ ...actionStyle(isDesktop, filled), opacity: pending ? 0.5 : 1 }}
            >
              {content}
            </button>
          );
        })}
      </div>
    )
  );

  const identity = (
    <div style={{ minWidth: 0 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12, flexWrap: 'wrap' }}>
        <span style={{ fontSize: 10, letterSpacing: 1.5, padding: '4px 10px', border: `1px solid ${LEAF_30}`, color: LEAF }}>
          {TYPE_LABEL[type] || 'GUEST'}
        </span>
        {entity.role && (
          <span style={{ fontSize: 11, letterSpacing: 1, padding: '4px 10px', border: `1px solid ${LEAF_30}`, color: LEAF, opacity: 0.8 }}>
            {String(entity.role).toUpperCase()}
          </span>
        )}
      </div>

      <h2 style={{ margin: '0 0 10px', fontSize: isDesktop ? 32 : 24, lineHeight: 1.15, color: LEAF, overflowWrap: 'anywhere' }}>
        {entity.name || entity.company || 'UNNAMED'}
      </h2>

      <p style={{ margin: '0 0 16px', fontSize: 14, lineHeight: 1.7, color: 'rgba(171,212,158,0.8)' }}>
        {type === 'ATTENDEE' && `Registered for ${eventName}.`}
        {type === 'TALENT' && (entity.bio || 'Performing at this event.')}
        {type === 'EXHIBITOR' && `${entity.description || 'Trading at this event.'}${entity.services ? ` — ${entity.services}` : ''}`}
      </p>

      <div style={{ height: 1, backgroundColor: LEAF, opacity: 0.25, margin: isDesktop ? '24px 0' : '20px 0' }} />
      {actionRow}
    </div>
  );

  const productsSection = type === 'EXHIBITOR' && products.length > 0 && (
    <div style={{ gridColumn: isDesktop ? '1 / -1' : 'auto', marginTop: isDesktop ? 12 : 4 }}>
      <h3 style={{ margin: '0 0 14px', fontSize: 16, textAlign: isDesktop ? 'left' : 'center', color: LEAF }}>
        Available products and services
      </h3>
      <div style={{ height: 1, backgroundColor: LEAF, opacity: 0.25, marginBottom: 18 }} />
      <div style={{ display: 'grid', gridTemplateColumns: isDesktop ? 'repeat(auto-fill, minmax(260px, 1fr))' : '1fr', gap: 16 }}>
        {products.map((p, i) => (
          <div key={p._id || i} style={{ border: `1px solid ${LEAF_30}`, display: 'flex', flexDirection: 'column' }}>
            {p.image && (
              <div style={{ height: 150, backgroundColor: LEAF_08, borderBottom: `1px solid ${LEAF_30}` }}>
                <img src={p.image} alt={p.name || ''} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              </div>
            )}
            <div style={{ padding: 16 }}>
              <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 6, color: LEAF }}>{p.name}</div>
              {p.description && (
                <div style={{ fontSize: 13, lineHeight: 1.6, color: 'rgba(171,212,158,0.75)' }}>{p.description}</div>
              )}
              {/* Price and wait time render only when the listing carries them — this row
                  used to print "₦undefined" for every exhibitor product, because the
                  seeded products have no price field. */}
              {(typeof p.price === 'number' || p.waitTime) && (
                <div style={{ display: 'flex', marginTop: 14, border: `1px solid ${LEAF_30}` }}>
                  {typeof p.price === 'number' && (
                    <div style={{ flex: 1, padding: '8px 12px', borderRight: `1px solid ${LEAF_30}`, fontSize: 13, fontWeight: 600, color: LEAF }}>
                      ₦{p.price.toLocaleString()}
                    </div>
                  )}
                  {p.waitTime && (
                    <div style={{ padding: '8px 12px' }}>
                      <div style={{ fontSize: 9, letterSpacing: 1, color: 'rgba(171,212,158,0.6)' }}>WAIT TIME</div>
                      <div style={{ fontSize: 12, color: LEAF }}>{p.waitTime}</div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );


  // ── Desktop: centred dialog over a dimmed backdrop ──────────────────────────
  if (isDesktop) {
    return (
      <div
        onMouseDown={(e) => { if (e.target === e.currentTarget) onClose?.(); }}
        style={{
          position: 'fixed', inset: 0, zIndex: 10000,
          backgroundColor: 'rgba(10,10,9,0.72)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          padding: 32,
        }}
      >
        <div
          role="dialog"
          aria-modal="true"
          aria-label={`${entity.name || 'Entity'} — ${TYPE_LABEL[type] || 'GUEST'}`}
          style={{
            position: 'relative',
            width: 'min(1040px, 94vw)',
            maxHeight: '88vh',
            overflowY: 'auto',
            backgroundColor: INK,
            border: `1px solid ${LEAF}`,
            boxShadow: '0 24px 80px rgba(0,0,0,0.6)',
          }}
        >
          <div style={{ position: 'sticky', top: 0, zIndex: 2, display: 'flex', alignItems: 'center', gap: 12, height: 60, padding: '0 20px', backgroundColor: INK, borderBottom: `1px solid ${LEAF_30}` }}>
            <button onClick={onClose} aria-label="Back" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: 36, height: 36, background: 'none', border: `1px solid ${LEAF_30}`, color: LEAF, cursor: 'pointer' }}>
              <ArrowLeft size={18} />
            </button>
            <span style={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 14, color: LEAF }}>{eventName}</span>
            <button onClick={onClose} aria-label="Close" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: 36, height: 36, background: 'none', border: `1px solid ${LEAF_30}`, color: LEAF, cursor: 'pointer' }}>
              <X size={18} />
            </button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'minmax(300px, 380px) 1fr', gap: 32, padding: 32 }}>
            <div style={{ aspectRatio: '4 / 5', backgroundColor: LEAF_08, border: `1px solid ${LEAF_30}`, overflow: 'hidden' }}>
              {imageSrc && <img src={imageSrc} alt={entity.name || ''} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />}
            </div>
            {identity}
            {productsSection}
          </div>
        </div>
      </div>
    );
  }

  // ── Phone: full-screen sheet ────────────────────────────────────────────────
  return (
    <div style={{ position: 'fixed', inset: 0, backgroundColor: INK, zIndex: 10000, overflowY: 'auto' }}>
      <div style={{ position: 'sticky', top: 0, zIndex: 2, display: 'flex', alignItems: 'center', gap: 10, height: 54, padding: '0 16px', backgroundColor: INK, borderBottom: `1px solid ${LEAF_30}` }}>
        <button onClick={onClose} aria-label="Back" style={{ display: 'flex', alignItems: 'center', background: 'none', border: 'none', color: LEAF, cursor: 'pointer', padding: 0 }}>
          <ArrowLeft size={22} />
        </button>
        <span style={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 14, color: LEAF }}>{eventName}</span>
        <span style={{ fontSize: 10, letterSpacing: 1.5, color: LEAF, opacity: 0.7 }}>{TYPE_LABEL[type] || 'GUEST'}</span>
      </div>

      <div style={{ padding: 20, paddingBottom: 80 }}>
        {imageSrc && (
          <div style={{ aspectRatio: '16 / 10', backgroundColor: LEAF_08, border: `1px solid ${LEAF_30}`, marginBottom: 20, overflow: 'hidden' }}>
            <img src={imageSrc} alt={entity.name || ''} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
        )}
        {identity}
        <div style={{ marginTop: 8 }}>{productsSection}</div>
      </div>
    </div>
  );
}

